(()=>{'use strict';const C=window.CBL=window.CBL||{},$=C.$,$$=C.$$;C.labs={};
C.register=(slug,fn)=>C.labs[slug]=fn;
C.bitsLab=(el,weights,kind='decimal')=>{let a=Array(weights.length).fill(0);el.innerHTML=`<div class="lab"><div class="lab-help">好きなスイッチを2〜3個押してください。ONになった桁だけ値に足されます。</div><div class="switch-grid">${weights.map((w,i)=>`<button type="button" class="bit-btn" data-i="${i}" aria-pressed="false"><small>${w}</small><b>0</b><em>OFF</em></button>`).join('')}</div><div class="result" aria-live="polite"><small>${kind==='hex'?'16進数':'10進数'}</small><strong data-result>0</strong><span class="subresult" data-sub>0</span></div><div class="interpret" data-interpret></div></div>`;const render=()=>{const val=weights.reduce((s,w,i)=>s+w*a[i],0),on=weights.filter((_,i)=>a[i]);$('[data-result]',el).textContent=kind==='hex'?val.toString(16).toUpperCase():val;$('[data-sub]',el).textContent=kind==='hex'?`${val} (10進数)`:on.length?on.join(' + ')+' = '+val:'0';$('[data-interpret]',el).innerHTML=`<strong>読み取れること:</strong> ${on.length?`ONの ${on.join('・')} を足すと ${val}。0/1の並びを数として読めました。`:'OFFは0。ONにした桁だけ値に加わります。'}`};$$('.bit-btn',el).forEach(b=>b.onclick=()=>{const i=+b.dataset.i;a[i]^=1;b.classList.toggle('on',!!a[i]);b.setAttribute('aria-pressed',!!a[i]);$('b',b).textContent=a[i];$('em',b).textContent=a[i]?'ON':'OFF';render()});render()};
C.flowLab=(el,cfg)=>{let mode=cfg.defaultMode||Object.keys(cfg.modes||{})[0]||'',step=-1,timer=null;const data=()=>cfg.modes?cfg.modes[mode]:cfg;el.innerHTML=`<div class="lab"><div class="lab-help">${cfg.help||'「次へ」を押して、どこで何が起きるかを順番に追ってください。'}</div><div data-modes></div><div class="lab-controls"><button type="button" class="btn primary" data-next>次へ</button><button type="button" class="btn" data-auto>自動で見る</button><button type="button" class="btn" data-reset>最初から</button></div><div class="result" aria-live="polite"><small>いま起きていること</small><strong style="font-size:18px" data-message>開始前</strong><span class="subresult" data-detail></span></div><div class="flow" data-flow></div><div class="timeline" data-timeline></div><div class="interpret" data-interpret></div></div>`;if(cfg.modes){const m=$('[data-modes]',el);m.className='mode-tabs';m.innerHTML=Object.entries(cfg.modes).map(([k,v])=>`<button type="button" class="btn ${k===mode?'active':''}" data-mode="${k}">${v.label}</button>`).join('');$$('[data-mode]',el).forEach(b=>b.onclick=()=>{mode=b.dataset.mode;$$('[data-mode]',el).forEach(x=>x.classList.toggle('active',x===b));reset()})}else $('[data-modes]',el).remove();const render=()=>{const d=data(),s=d.steps[step],f=$('[data-flow]',el);f.style.setProperty('--flow-cols',d.nodes.length*2-1);f.classList.toggle('horizontal',d.nodes.length<=5);f.innerHTML=d.nodes.map((n,i)=>`<div class="flow-node" data-node="${i}"><strong>${n[0]}</strong><span>${n[1]||''}</span></div>${i<d.nodes.length-1?`<div class="flow-arrow" data-arrow="${i}"></div>`:''}`).join('');$('[data-message]',el).textContent=step<0?(d.startTitle||'開始前'):s.title;$('[data-detail]',el).textContent=step<0?d.start:s.text;if(step>=0){$$('[data-node]',f).forEach((x,i)=>{x.classList.toggle('active',i===s.to);x.classList.toggle('done',i<s.to&&s.dir!=='back')});$$('[data-arrow]',f).forEach((x,i)=>x.classList.toggle('active',i===s.arrow))}$('[data-timeline]',el).innerHTML=d.steps.map((x,i)=>`<div class="timeline-item ${i===step?'active':i<step?'done':''}"><div class="n">${i+1}</div><div><strong>${x.title}</strong><span>${x.short||x.text}</span></div></div>`).join('');$('[data-interpret]',el).innerHTML=`<strong>ここで理解する:</strong> ${step<0?(d.takeawayStart||'順番そのものより、各仕組みが何のためにあるかを見ます。'):(s.takeaway||d.takeaway)}`};const next=()=>{if(step<data().steps.length-1){step++;render()}},reset=()=>{clearInterval(timer);step=-1;render()};$('[data-next]',el).onclick=next;$('[data-reset]',el).onclick=reset;$('[data-auto]',el).onclick=()=>{reset();next();timer=setInterval(()=>step>=data().steps.length-1?clearInterval(timer):next(),1200)};render()};
C.initLab=()=>{const el=$('[data-lab]'),s=document.body.dataset.lesson;if(el&&s&&C.labs[s])C.labs[s](el)}
})();